package br.com.confirmacao.session.api;
import br.com.confirmacao.audit.application.AuditService;import br.com.confirmacao.audit.domain.AuditAction;import br.com.confirmacao.session.application.SessionSeriesService;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/sessions/series") public class SessionSeriesController{private final SessionSeriesService service;private final AuditService audit;public SessionSeriesController(SessionSeriesService s,AuditService a){service=s;audit=a;}@PostMapping public List<SessionResponse> create(JwtAuthenticationToken jwt,@Valid @RequestBody SessionSeriesRequest r,HttpServletRequest h){return service.create(id(jwt),r.patientId(),r.startsAt(),r.endsAt(),r.modality(),r.meetingLink(),r.notes()).stream().map(session->{audit.record(AuditAction.SESSION_CREATED,"SESSION",session.getId(),h);return SessionResponse.from(session);}).toList();}private UUID id(JwtAuthenticationToken jwt){return UUID.fromString(jwt.getToken().getClaimAsString("professional_id"));}}
